-- JMSURF DASH module catalogue (generated from src/lib/modules.ts) and plans.
on conflict (key) do update set name = excluded.name, category = excluded.category, description = excluded.description,
  included = excluded.included, sort = excluded.sort, updated_at = now();

-- JMSURF BOOKS plans (users per company) + the All-in-One bundle.
update public.plans set is_active = false;
